import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        HashSet<String> full = new HashSet<>();
        ArrayList<HashSet<String>> pref = new ArrayList<>();
        ArrayList<HashSet<String>> suff = new ArrayList<>();

        for (int i = 0; i <= 10; i++) {
            pref.add(new HashSet<>());
            suff.add(new HashSet<>());
        }

        PrintWriter out = new PrintWriter(System.out);

        for (int k = 0; k < N; k++) {
            String s = br.readLine().trim();

            boolean invalid = full.contains(s);

            if (!invalid) {
                for (int L = 1; L <= 9; L++) {
                    String left = s.substring(0, L);
                    String right = s.substring(L, 10);

                    if (suff.get(L).contains(left) && pref.get(10 - L).contains(right)) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                out.println(s);
                out.flush();
                return;
            }

            full.add(s);

            for (int L = 1; L <= 9; L++) {
                pref.get(L).add(s.substring(0, L));
                suff.get(L).add(s.substring(10 - L, 10));
            }
        }

        out.println("ok");
        out.flush();
    }
}
